import csv, re, datetime
ALIAS={"taxi":"Travel","uber":"Travel","flight":"Travel","hotel":"Lodging","airbnb":"Lodging","lunch":"Meals","dinner":"Meals","coffee":"Meals","saas":"Software","software":"Software","license":"Software","books":"Learning","course":"Learning"}
MON={m:i for i,m in enumerate(["jan","feb","mar","apr","may","jun","jul","aug","sep","oct","nov","dec"],1)}
def pd(s):
    s=s.strip()
    for pat in [r"(\d{4})-(\d{1,2})-(\d{1,2})",r"(\d{1,2})/(\d{1,2})/(\d{4})",r"(\d{1,2}) ([A-Za-z]{3})\w* (\d{4})"]:
        m=re.fullmatch(pat,s)
        if m:
            if pat.startswith(r"(\d{4})"): y,mo,d=m.groups()
            elif pat.startswith(r"(\d{1,2})/"): mo,d,y=m.groups()
            else:
                d,mo,y=m.groups(); mo=MON[mo.lower()[:3]]
            return datetime.date(int(y),int(mo),int(d))
def cents(s):
    s=re.sub(r"USD|\$|,|\s","",s); w,_,f=s.partition(".")
    return int(w)*100+int((f+"00")[:2])
rows=list(csv.DictReader(open("expenses.csv",newline="")))
# filter first, then dedupe
valid=[r for r in rows if r["status"].strip().lower()!="void"]
valid=[r for r in valid if (pd(r["date"]).year,pd(r["date"]).month)==(2026,10)]
seen=set(); keep=[]
for r in valid:
    if r["id"] in seen: continue
    seen.add(r["id"]); keep.append(r)
print("rows kept",len(keep))
tot=0; cats={}; flags=[]
for r in keep:
    c=cents(r["amount"]); cat=ALIAS[r["category"].strip().lower()]
    n,s=cats.get(cat,(0,0)); cats[cat]=(n+1,s+c); tot+=c
    if c>50000: flags.append((int(r["id"]),c))
print("total",tot)
for k,(n,s) in sorted(cats.items(), key=lambda kv:(-kv[1][1],kv[0])): print(k,n,s)
print("flags",sorted(flags))
print("dup ids total occurrences:",len(rows)-len(set(r['id'] for r in rows)))
PY", "description": "Independently verify report totals and flags"}

